/**
 * The resolved `rune::Theme` for one appearance (every `--*` colour token by name, without `--`).
 * Translucent tokens resolve for the current blend mode as they are read (`rune::theme::blends_srgb`).
 */
export const opencode_theme: (dark: boolean) => Theme = $n.opencode_theme

/**
 * The brand's hot colour for one appearance: ember step 9, for marks like a logo or a
 * highlight that should read as the brand rather than the interactive accent.
 */
export const opencode_brand: (dark: boolean) => Color = $n.opencode_brand

/**
 * One step of the ember scale for one appearance, the same colour as the token
 * `ember-dark-<step>` or `ember-light-<step>`. `step` is 1 to 12; anything else panics.
 */
export const opencode_ember: (dark: boolean, step: number) => Color = $n.opencode_ember

/**
 * One step (1 to 12, else panics) of a named colour scale (`"amber"`, `"apple"`, `"blue"`,
 * `"cobalt"`, `"coral"`, `"ember"`, `"gray"`, `"ink"`, `"lilac"`, `"mint"`, `"smoke"`,
 * `"solaris"`, `"yuzu"`): the token `<name>-dark-<step>` or `<name>-light-<step>`. Panics if
 * the theme has no such token.
 */
export const opencode_scale: (name: string, dark: boolean, step: number) => Color = $n.opencode_scale

/**
 * The kit tokens for one appearance, resolved for the blend mode of the window building the
 * view (`rune::theme::blends_srgb`): translucent tokens as authored when it blends in sRGB,
 * re-solved over `bg_base` when it blends in linear light. Get it in the view rather than
 * keeping it across a `Tx::set_srgb_blend`.
 */
export const opencode_kit: (dark: boolean) => kit_Kit = $n.opencode_kit

